// export default ProtectedRoute;
const ProtectedRoute = ({ isLoggedIn, userRole, requiredRole, children }) => {
  if (!isLoggedIn) {
    return <Navigate to="/login" />;
  }

  if (requiredRole && userRole !== requiredRole) {
    return <Navigate to="/" />;
  }

  return children;
};









